r=Path(__file__).parent;state=json.loads((r/'DEVICE_STATUS.json').read_text());assert state['stage']=='DEVICE_PHASE_ENDED_ORIGINAL_RESTORED' and not (r/'FAILURE.json').exists();before=json.loads((r/'clock_pre.json').read_text());after=json.loads((r/'clock_post.json').read_text());drift=validate_calibration(before,after)
