selected=first_capture(events,v['rows'],before['offset_ns']);results=[dict(index=i,expected=e['expected'],selected=f,correct=bool(f and f['finite'] and f['pred']==e['expected'])) for i,(e,f) in enumerate(zip(events,selected))]
history=v['summary']['history'].splitlines();assert history[0]=='RML24_HISTORY_V2';h=[line.split() for line in history[1:]];assert [int(x[6]) for x in h[:3]]==[3,4,3];assert all(x[0]==before['board_boot_id'] and 0<=int(x[1])<=int(x[2])<10000000 for x in h)
out=dict(kind='UI_AND_MONOTONIC_TIMING_FUNCTIONAL_SHORT_NOT_FORMAL_REGRESSION',denominator=3,correct=sum(x['correct'] for x in results),results=results,clock_drift_ns=drift,pre_uncertainty_ns=before['uncertainty_ns'],post_uncertainty_ns=after['uncertainty_ns'],history_episode_labels=[int(x[6]) for x in h],history_uptime_valid=True,receiver_clean=True,fpga_calls=v['summary']['backend_counts'],original_restored=True)
(r/'UI_TIMING_RF_RECEIPT.json').write_text(json.dumps(out,indent=2),encoding='utf-8');print(json.dumps({k:x for k,x in out.items() if k!='results'}))
